const r = phi.click(29);
phi.sleep(1500);
const o = phi.observe();
return { r, url: o.url, title: o.title, nodes: o.nodes.slice(0, 70).map(n => `${n.ref}. ${n.role} "${n.name || n.text}"`) };

const full = phi.recall("$step5") || phi.text();
const tail = full.slice(3000);
const rows = phi.query("#compare-tiers table tr, table tr", { limit: 40 });
return { tail, rowCount: rows.total };

const tbl = phi.js(() => {
  const tables = [...document.querySelectorAll('table')];
  return tables.map(t => ({
    rows: [...t.querySelectorAll('tr')].map(tr => [...tr.querySelectorAll('th,td')].map(c => c.innerText.replace(/\s+/g, ' ').trim()))
  }));
});
const out = tbl.map((t, i) => `TABLE ${i} rows=${t.rows.length} first=${JSON.stringify(t.rows[0])} last=${JSON.stringify(t.rows[t.rows.length-1])}`);
return out;

const rows = phi.js(() => {
  const t = document.querySelectorAll('table')[0];
  return [...t.querySelectorAll('tr')].map(tr => [...tr.querySelectorAll('th,td')].map(c => c.innerText.replace(/\s+/g, ' ').trim()));
});
phi.keep("plans_table", rows);
return rows.map(r => r.join(" | "));

const res = phi.js(() => {
  const tables = [...document.querySelectorAll('table')];
  const clean = t => [...t.querySelectorAll('tr')].map(tr => [...tr.querySelectorAll('th,td')].map(c => c.innerText.replace(/\s+/g,' ').trim()).slice(0,3));
  const vol = clean(tables[9]);
  const samples = {};
  const names = {1:'maps',2:'foresight',3:'airports',4:'operators',5:'alerts',6:'history',7:'disruption',8:'account'};
  for (const k of [1,2,3,4,5,6,7,8]) {
    const rows = clean(tables[k]);
    samples[names[k]] = rows.slice(1).map(r => r[0].slice(0,60) + ' => ' + (r[1]||''));
  }
  return { vol, samples };
});
phi.keep("pricing_detail", res);
return res;

const doc = phi.observe({ maxElements: 40 });
phi.narrate("Checking the developer portal, then the English plan page for exact prices");
const nav = phi.goto("https://www.flightaware.com/commercial/aeroapi/#compare-tiers");
const cards = phi.js(() => {
  const txt = document.body.innerText;
  return txt.slice(0, 3000);
});
return { docTitle: doc.title, docText: (doc.text||"").slice(0,800), nav, cards };

const plans = phi.recall("plans_table");
const pd = phi.recall("pricing_detail");
return { plans, pdKeys: Object.keys(pd), vol: pd.vol };

const pd = phi.recall("pricing_detail");
const samples = pd.samples;
// check whether per-query fee table exists on page now
const t = phi.text();
const idx = t.indexOf("Per-Query");
return { samplesHead: (samples||[]).slice(0,12), sampleCount: (samples||[]).length, idx, around: idx>-1 ? t.slice(Math.max(0,idx-200), idx+1200) : t.slice(0,600) };

const obs = phi.observe({ maxElements: 60 });
const info = phi.js(() => {
  const h = Array.from(document.querySelectorAll("h1,h2,h3")).map(e => e.innerText.trim()).filter(Boolean).slice(0, 40);
  const t = document.body.innerText;
  const idx = t.toLowerCase().indexOf("compare");
  return {
    headings: h,
    entMention: (t.match(/enterprise/gi) || []).length,
    hasCompare: idx > -1,
    around: idx > -1 ? t.slice(Math.max(0, idx - 300), idx + 900) : t.slice(0, 900),
    title: document.title
  };
});
return { pageTitle: obs.title, nodes: obs.nodes.slice(0, 25), total: obs.total, info };

const r = phi.goto("https://www.flightaware.com/commercial/aeroapi/");
const info = phi.js(() => {
  const t = document.body.innerText;
  const i = t.toLowerCase().indexOf("find the right tier");
  const j = t.toLowerCase().indexOf("trusted globally");
  return {
    url: location.href,
    title: document.title,
    tierSection: i > -1 ? t.slice(i, i + 1800) : t.slice(0, 1500),
    afterTier: (i > -1 && j > i) ? t.slice(i, j) : null,
    enterprise: (t.match(/enterprise/gi) || []).length,
    freeTrial: /free trial|try aeroapi/i.test(t)
  };
});
return { nav: r && r.url, info };

const pt = phi.recall("plans_table");
const r = phi.js(() => {
  const t = document.body.innerText;
  const i = t.indexOf("Pricing Details");
  return { url: location.href, title: document.title, pricing: i > -1 ? t.slice(i, i + 2500) : null };
});
return { plans: pt, pricingSection: r.pricing, url: r.url };

const pd = phi.recall("pricing_detail");
const s = JSON.stringify(pd);
const page = phi.js(() => {
  const t = document.body.innerText;
  const out = {};
  ["per-query fees","Per-Query Fees","Free monthly","result set"].forEach(k => {
    const i = t.indexOf(k);
    if (i > -1 && !out["at_" + k]) out["at_" + k] = true;
  });
  const i = t.indexOf("Volume Discounting", t.indexOf("Volume Discounting") + 10);
  out.volSection = i > -1 ? t.slice(i, i + 1400) : null;
  return out;
});
return { keys: Object.keys(pd || {}), preview: s.slice(0, 2600), page };

const r = phi.js(() => {
  const t = document.body.innerText;
  const lower = t.toLowerCase();
  const out = {};
  out.url = location.href;
  out.title = document.title;
  // any tier/plan names beyond three
  out.enterpriseMentions = (lower.match(/enterprise/gi) || []).length;
  const idxEnt = lower.indexOf("enterprise");
  out.enterpriseContext = idxEnt > -1 ? t.slice(Math.max(0, idxEnt - 300), idxEnt + 500) : null;
  // free trial / free allowance wording
  const iFree = lower.search(/free trial|try aeroapi|get started|free/i);
  out.freeSnippets = [];
  const re = /[^.\n]{0,120}(free trial|try aeroapi|\$\d[\d,]* free)[^.\n]{0,120}/gi;
  let m; let k = 0;
  while ((m = re.exec(t)) && k < 8) { out.freeSnippets.push(m[0].trim()); k++; }
  // plan tier cards with their CTA hrefs
  const links = Array.from(document.querySelectorAll('a')).map(a => ({ txt: (a.innerText || '').trim().replace(/\s+/g, ' ').slice(0, 60), href: a.getAttribute('href') }))
    .filter(l => /get started|sign up|contact|start free|try/i.test(l.txt));
  out.ctas = links.slice(0, 20);
  return out;
});
return r;

const r = phi.js(() => {
  const t = document.body.innerText;
  const i = t.indexOf("Personal");
  const head = t.slice(0, 1800);
  // plan card blurbs: find the section repeating Personal/Standard/Premium early
  return { url: location.href, head };
});
return r;

const pt = phi.recall("plans_table");
const r = phi.js(() => {
  const t = document.body.innerText;
  // find the pricing tiers section
  const i = t.indexOf("Pricing Tiers");
  const j = t.indexOf("Compare tiers");
  const k = t.toLowerCase().indexOf("why aeroapi");
  const out = {};
  out.pricingSection = i > -1 ? t.slice(i, i + 1800) : null;
  out.beforeCompare = j > -1 ? t.slice(Math.max(0, j - 2000), j + 40) : null;
  out.monthlyMentions = [];
  const re = /[^\n]{0,80}(\$\s?\d[\d,]*)[^\n]{0,80}/g; let m, c = 0;
  while ((m = re.exec(t)) && c < 40) { out.monthlyMentions.push(m[0].trim()); c++; }
  return out;
});
return { plansTable: pt, page: r };

const r = phi.js(() => {
  const t = document.body.innerText;
  const out = {};
  const re = /[^\n]*\bfree\b[^\n]*/gi;
  const fm = []; let m, c = 0;
  while ((m = re.exec(t)) && c < 25) { fm.push(m[0].trim()); c++; }
  out.freeMentions = fm;
  // CTA links
  out.ctas = [...document.querySelectorAll('a')]
    .filter(a => /start|sign|trial|console|get started|开始|注册|免费/i.test(a.innerText))
    .slice(0, 15)
    .map(a => ({ t: a.innerText.trim().slice(0, 40), href: a.getAttribute('href') }));
  return out;
});
return r;

